/**
 * Shared types for the MCP server.
 * SchemaData interfaces are duplicated from scripts/generate-skill/schema-parser.ts
 * to avoid cross-package import complexity.
 */
export interface ContentSection {
    title: string;
    body: string;
    sourceFile: string;
    /** Keywords extracted from title for boosted matching */
    keywords: string[];
}
export interface SearchResult {
    title: string;
    sourceFile: string;
    preview: string;
    score: number;
}
export interface ScalarType {
    name: string;
    description: string;
}
export interface EnumValue {
    name: string;
    description?: string;
}
export interface EnumType {
    name: string;
    description?: string;
    values: EnumValue[];
}
export interface FieldArg {
    name: string;
    type: string;
    required: boolean;
    default?: string;
    description?: string;
}
export interface ObjectField {
    name: string;
    type: string;
    required: boolean;
    description?: string;
    args?: FieldArg[];
}
export interface ObjectType {
    name: string;
    description?: string;
    fields: ObjectField[];
    implements?: string[];
}
export interface InterfaceType {
    name: string;
    description?: string;
    fields: ObjectField[];
    implements?: string[];
}
export interface InputType {
    name: string;
    description?: string;
    fields: ObjectField[];
}
export interface RootQuery {
    name: string;
    description: string;
    args: FieldArg[];
    returnType: string;
    returnRequired: boolean;
    isList: boolean;
}
export interface SchemaData {
    scalars: ScalarType[];
    enums: EnumType[];
    interfaces: InterfaceType[];
    objectTypes: ObjectType[];
    inputTypes: InputType[];
    rootQueries: RootQuery[];
}
